/** @file  FBXParser.cpp
 *  @brief Implementation of the FBX parser and the rudimentary DOM that we use
 */

#ifndef ASSIMP_BUILD_NO_FBX_IMPORTER

//#ifdef ASSIMP_BUILD_NO_OWN_ZLIB
#include "Common/Compression.h"
